create schema if not exists pricing;

grant usage on schema pricing to authenticated, service_role;

create table if not exists pricing.customer_price_rules (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  customer_id uuid not null,
  product_id uuid not null,
  product_unit_id uuid not null,
  customer_display_name_snapshot text not null,
  customer_status_snapshot text not null,
  product_name_snapshot text not null,
  product_reference_id_snapshot text not null,
  product_sku_snapshot text,
  unit_name_snapshot text not null,
  sellable_status_snapshot text not null,
  rule_price_minor bigint not null check (rule_price_minor > 0),
  currency_code text not null check (currency_code ~ '^[A-Z]{3}$'),
  rule_type text not null default 'special_price'
    check (rule_type in ('special_price')),
  source_type text not null default 'manual'
    check (source_type in ('manual')),
  status text not null default 'active'
    check (status in ('active', 'disabled', 'needs_review', 'deleted')),
  review_status text not null default 'clear'
    check (review_status in ('clear', 'warning', 'blocked', 'needs_review')),
  effective_from date not null,
  effective_to date,
  list_price_snapshot_minor bigint,
  floor_price_snapshot_minor bigint,
  price_check_status text not null
    check (price_check_status in ('not_checked', 'normal', 'override_allowed')),
  warning_codes jsonb not null default '[]'::jsonb,
  blocking_codes jsonb not null default '[]'::jsonb,
  note text,
  disabled_at timestamptz,
  disabled_by uuid,
  disabled_reason text,
  created_by uuid not null,
  created_at timestamptz not null default statement_timestamp(),
  updated_by uuid not null,
  updated_at timestamptz not null default statement_timestamp(),
  version integer not null default 1 check (version > 0),
  idempotency_key text not null,
  payload_hash text not null,
  constraint customer_price_rules_period_valid
    check (effective_to is null or effective_to >= effective_from),
  constraint customer_price_rules_disabled_reason_length
    check (disabled_reason is null or length(disabled_reason) <= 500),
  constraint customer_price_rules_disabled_audit_complete
    check (
      status <> 'disabled'
      or (disabled_at is not null and disabled_by is not null)
    ),
  constraint customer_price_rules_idempotency_unique
    unique (tenant_id, idempotency_key)
);

create index if not exists customer_price_rules_active_key_idx
  on pricing.customer_price_rules (
    tenant_id,
    customer_id,
    product_id,
    product_unit_id,
    effective_from,
    effective_to
  )
  where status = 'active';

create table if not exists pricing.customer_price_rule_activities (
