create or replace function pricing._customer_price_rule_result(
  p_rule_id uuid,
  p_can_view_floor boolean
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'rule', jsonb_build_object(
      'id', r.id,
      'customer', jsonb_build_object(
        'customer_id', r.customer_id,
        'display_name', r.customer_display_name_snapshot,
        'status', r.customer_status_snapshot
      ),
      'product_unit', jsonb_build_object(
        'product_id', r.product_id,
        'product_unit_id', r.product_unit_id,
        'product_name', r.product_name_snapshot,
        'product_reference_id', r.product_reference_id_snapshot,
        'sku', r.product_sku_snapshot,
        'unit_name', r.unit_name_snapshot,
        'sellable_status', r.sellable_status_snapshot
      ),
      'price', jsonb_build_object(
        'amount_minor', r.rule_price_minor,
        'currency_code', r.currency_code
      ),
      'effective_period', jsonb_build_object(
        'effective_from', r.effective_from,
        'effective_to', r.effective_to
      ),
      'rule_type', r.rule_type,
      'source_type', r.source_type,
      'persisted_status', r.status,
      'derived_status', case
        when r.status = 'disabled' then 'disabled'
        when r.status = 'needs_review'
          or r.review_status in ('blocked', 'needs_review')
          or jsonb_array_length(r.blocking_codes) > 0 then 'needs_review'
        when r.effective_to is not null
          and r.effective_to < current_date then 'expired'
        when r.effective_from > current_date then 'not_yet_effective'
        else 'applying'
      end,
      'note', r.note,
      'disabled_at', r.disabled_at,
      'disabled_by', r.disabled_by,
      'disabled_reason', r.disabled_reason,
      'validation_outcome', jsonb_build_object(
        'outcome', case r.price_check_status
          when 'not_checked' then 'notChecked'
          when 'override_allowed' then 'warning'
          else 'valid'
        end,
        'warning_codes', r.warning_codes,
        'blocking_codes', r.blocking_codes,
        'list_price', case
          when r.list_price_snapshot_minor is null then null
          else jsonb_build_object(
            'amount_minor', r.list_price_snapshot_minor,
            'currency_code', r.currency_code
          )
        end,
        'floor_price', case
          when p_can_view_floor and r.floor_price_snapshot_minor is not null
            then jsonb_build_object(
              'amount_minor', r.floor_price_snapshot_minor,
              'currency_code', r.currency_code
            )
          else null
        end,
        'floor_price_hidden',
          r.floor_price_snapshot_minor is not null and not p_can_view_floor
      ),
      'reference_health', jsonb_build_object(
        'customer_state', 'valid',
        'product_unit_state', 'valid',
        'price_band_state', case
          when r.price_check_status in (
            'not_checked',
            'normal',
            'override_allowed'
          ) then 'current'
          else 'unavailable'
        end,
        'issue_codes', '[]'::jsonb,
        'used_stored_price_band_snapshot', false
      ),
      'source_trace', jsonb_build_object(
        'hidden', false,
        'source_import_id', null,
        'source_import_row_id', null,
        'source_order_id', null,
        'source_order_line_id', null
      ),
      'created_by', r.created_by,
      'created_at', r.created_at,
      'updated_by', r.updated_by,
      'updated_at', r.updated_at,
      'version', r.version,
      'available_actions', (
        select coalesce(jsonb_agg(action order by ordinality), '[]'::jsonb)
        from (
          select action, ordinality
          from unnest(
            array[
              case
                when r.status in ('active', 'needs_review', 'disabled')
                  and iam.has_permission(
                    r.tenant_id,
                    'pricing.customer_price_rule.update'
                  )
                then 'edit'
              end,
              case
                when r.status in ('active', 'needs_review')
                  and iam.has_permission(
                    r.tenant_id,
                    'pricing.customer_price_rule.disable'
                  )
                then 'disable'
              end,
              case
                when r.status = 'disabled'
                  and iam.has_permission(
                    r.tenant_id,
                    'pricing.customer_price_rule.reenable'
                  )
                then 'reenable'
              end,
              case
                when iam.has_permission(
                  r.tenant_id,
                  'pricing.customer_price_rule.view_history'
                )
                then 'history'
              end
            ]
          ) with ordinality as t(action, ordinality)
          where action is not null
        ) actions
      )
    ),
    'warnings', coalesce(
      (
        select jsonb_agg(jsonb_build_object('code', warning_code))
        from jsonb_array_elements_text(r.warning_codes) as warning_code
      ),
      '[]'::jsonb
    )
  )
  from pricing.customer_price_rules r
  where r.id = p_rule_id;
$$;

revoke all on function pricing._customer_price_rule_result(uuid, boolean)
  from public, anon, authenticated, service_role;

create or replace function pricing._auto_disable_overlapping_customer_price_rules(
  p_tenant_id uuid,
  p_keep_rule_id uuid,
  p_customer_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid,
  p_effective_from date,
  p_effective_to date,
  p_actor_id uuid,
  p_replacement_action text
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reason text :=
      'Tự động tắt do bị ghi đè bởi giá riêng ' || p_keep_rule_id::text;
  v_disabled_count integer := 0;
begin
  with locked as (
    select r.id, r.version, r.status, r.disabled_at, r.disabled_by, r.disabled_reason
    from pricing.customer_price_rules r
    where r.tenant_id = p_tenant_id
      and r.id <> coalesce(p_keep_rule_id, '00000000-0000-0000-0000-000000000000'::uuid)
      and r.customer_id = p_customer_id
      and r.product_id = p_product_id
      and r.product_unit_id = p_product_unit_id
      and r.status = 'active'
      and r.effective_from <= coalesce(p_effective_to, 'infinity'::date)
      and p_effective_from <= coalesce(r.effective_to, 'infinity'::date)
    for update
  ),
  updated as (
    update pricing.customer_price_rules r
    set status = 'disabled',
        disabled_reason = v_reason,
        disabled_by = p_actor_id,
        disabled_at = statement_timestamp(),
        updated_by = p_actor_id,
        updated_at = statement_timestamp(),
        version = r.version + 1
    from locked l
    where r.id = l.id
    returning
      r.id,
      l.version as old_version,
      r.version as new_version,
      r.status,
      r.disabled_at,
      r.disabled_by,
      r.disabled_reason
  ),
  activity as (
    insert into pricing.customer_price_rule_activities (
      tenant_id,
      customer_price_rule_id,
      activity_type,
      old_value,
      new_value,
      created_by
    )
    select
      p_tenant_id,
      u.id,
      'disabled',
      jsonb_build_object(
        'status', 'active',
        'version', u.old_version
      ),
      jsonb_build_object(
        'status', u.status,
        'version', u.new_version,
        'disabled_at', u.disabled_at,
        'disabled_by', u.disabled_by,
        'disabled_reason', u.disabled_reason,
        'reason_code', 'AUTO_REPLACED_BY_RULE',
        'replacement_rule_id', p_keep_rule_id,
        'replacement_action', p_replacement_action
      ),
      p_actor_id
    from updated u
    returning 1
  )
  select count(*)::integer into v_disabled_count from activity;

  return v_disabled_count;
end;
$$;

revoke all on function pricing._auto_disable_overlapping_customer_price_rules(
  uuid, uuid, uuid, uuid, uuid, date, date, uuid, text
) from public, anon, authenticated, service_role;

create or replace function pricing.create_customer_price_rule(
  p_tenant_id uuid,
  p_rule_id uuid,
  p_customer_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid,
  p_rule_price_minor bigint,
  p_currency_code text,
  p_effective_from date,
  p_idempotency_key text,
  p_effective_to date default null,
  p_note text default null,
  p_acknowledge_floor_warning boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := auth.uid();
  v_customer jsonb;
  v_product jsonb;
  v_existing pricing.customer_price_rules%rowtype;
  v_rule pricing.customer_price_rules%rowtype;
  v_can_override_floor boolean := false;
  v_floor_price_minor bigint;
  v_list_price_minor bigint;
  v_is_below_floor boolean := false;
  v_payload jsonb;
  v_payload_hash text;
  v_conflicting_rule_id uuid;
  v_warning_codes jsonb := '[]'::jsonb;
  v_price_check_status text := 'not_checked';
  v_review_status text := 'clear';
begin
  if v_actor_id is null
    or not iam.has_permission(
      p_tenant_id,
      'pricing.customer_price_rule.create'
    ) then
    perform pricing._raise_pricing_error(
      'NO_PERMISSION',
      'Permission denied.',
      jsonb_build_object('permission', 'pricing.customer_price_rule.create')
    );
  end if;

  if p_rule_id is null
    or p_rule_price_minor is null or p_rule_price_minor <= 0
    or p_currency_code !~ '^[A-Z]{3}$'
    or p_effective_from is null
    or (p_effective_to is not null and p_effective_to < p_effective_from)
    or nullif(btrim(p_idempotency_key), '') is null then
    perform pricing._raise_pricing_error(
      'VALIDATION_ERROR',
      'Invalid customer price rule payload.'
    );
  end if;

  v_payload := jsonb_build_object(
    'tenant_id', p_tenant_id,
    'customer_id', p_customer_id,
    'product_id', p_product_id,
    'product_unit_id', p_product_unit_id,
    'rule_price_minor', p_rule_price_minor,
    'currency_code', p_currency_code,
    'effective_from', p_effective_from,
    'effective_to', p_effective_to,
    'note', nullif(btrim(p_note), ''),
    'acknowledge_floor_warning',
      coalesce(p_acknowledge_floor_warning, false)
  );
  v_payload_hash := md5(v_payload::text);

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_tenant_id::text || ':idempotency:' || btrim(p_idempotency_key),
      0
    )
  );

  select r.*
  into v_existing
  from pricing.customer_price_rules r
  where r.tenant_id = p_tenant_id
    and r.idempotency_key = btrim(p_idempotency_key);

  if found then
    if v_existing.payload_hash <> v_payload_hash then
      perform pricing._raise_pricing_error(
        'IDEMPOTENCY_CONFLICT',
        'Idempotency key was already used with a different payload.',
        jsonb_build_object('idempotencyKey', btrim(p_idempotency_key))
      );
    end if;

    v_can_override_floor := iam.has_permission(
      p_tenant_id,
      'pricing.customer_price_rule.override_floor_price'
    );
    return pricing._customer_price_rule_result(
      v_existing.id,
      v_can_override_floor
    );
  end if;

  v_customer := partner._get_customer_snapshot_for_pricing(
    p_tenant_id,
    p_customer_id
  );
  v_product := catalog._get_product_price_band_snapshot_for_pricing(
    p_tenant_id,
    p_product_id,
    p_product_unit_id
  );

  if not coalesce((v_customer ->> 'exists')::boolean, false)
    or not coalesce((v_customer ->> 'is_customer')::boolean, false)
    or coalesce(v_customer ->> 'status', '') <> 'active' then
    perform pricing._raise_pricing_error(
      'REFERENCE_INVALID',
      'Customer is not valid for pricing.',
      jsonb_build_object('reference', 'customer')
    );
  end if;

  if not coalesce((v_product ->> 'exists')::boolean, false)
    or not coalesce((v_product ->> 'sellable')::boolean, false)
    or not coalesce((v_product ->> 'minor_units_valid')::boolean, false)
    or coalesce(v_product ->> 'currency_code', '') <> p_currency_code then
    perform pricing._raise_pricing_error(
      'REFERENCE_INVALID',
      'Product unit or price band is not valid for pricing.',
      jsonb_build_object('reference', 'productUnit')
    );
  end if;

  v_can_override_floor := iam.has_permission(
    p_tenant_id,
    'pricing.customer_price_rule.override_floor_price'
  );
  v_floor_price_minor := (v_product ->> 'floor_price_minor')::bigint;
  v_list_price_minor := (v_product ->> 'list_price_minor')::bigint;
  v_is_below_floor := v_floor_price_minor is not null
    and p_rule_price_minor < v_floor_price_minor;

  if v_is_below_floor
    and not coalesce(p_acknowledge_floor_warning, false) then
    perform pricing._raise_pricing_error(
      'BELOW_FLOOR_BLOCKED',
      'Below-floor price requires acknowledgement.',
      jsonb_build_object('reason', 'acknowledgementRequired')
    );
  end if;

  if v_is_below_floor and not v_can_override_floor then
    perform pricing._raise_pricing_error(
      'BELOW_FLOOR_BLOCKED',
      'Below-floor price requires override permission.',
      jsonb_build_object('reason', 'overridePermissionRequired')
    );
  end if;

  if v_is_below_floor then
    v_warning_codes := jsonb_build_array('below_floor_price');
    v_price_check_status := 'override_allowed';
    v_review_status := 'warning';
  elsif v_floor_price_minor is not null then
    v_price_check_status := 'normal';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_tenant_id::text || ':rule:' || p_customer_id::text || ':'
        || p_product_id::text || ':' || p_product_unit_id::text,
      0
    )
  );

  select r.id
  into v_conflicting_rule_id
  from pricing.customer_price_rules r
  where r.tenant_id = p_tenant_id
    and r.customer_id = p_customer_id
    and r.product_id = p_product_id
    and r.product_unit_id = p_product_unit_id
    and r.status = 'active'
    and r.effective_from <= coalesce(p_effective_to, 'infinity'::date)
    and p_effective_from <= coalesce(r.effective_to, 'infinity'::date)
  limit 1
  for update;

  if v_conflicting_rule_id is not null then
    perform pricing._raise_pricing_error(
      'DUPLICATE_ACTIVE_RULE',
      'An active customer price rule already overlaps this period.',
      jsonb_build_object('conflictingRuleId', v_conflicting_rule_id)
    );
  end if;

  insert into pricing.customer_price_rules (
    id,
    tenant_id,
    customer_id,
    product_id,
    product_unit_id,
    customer_display_name_snapshot,
    customer_status_snapshot,
    product_name_snapshot,
    product_reference_id_snapshot,
    product_sku_snapshot,
    unit_name_snapshot,
    sellable_status_snapshot,
    rule_price_minor,
    currency_code,
    review_status,
    effective_from,
    effective_to,
    list_price_snapshot_minor,
    floor_price_snapshot_minor,
    price_check_status,
    warning_codes,
    note,
    created_by,
    updated_by,
    idempotency_key,
    payload_hash
  ) values (
    p_rule_id,
    p_tenant_id,
    p_customer_id,
    p_product_id,
    p_product_unit_id,
    v_customer ->> 'display_name',
    v_customer ->> 'status',
    v_product ->> 'product_name',
    v_product ->> 'product_reference_id',
    v_product ->> 'sku',
    v_product ->> 'unit_name',
    v_product ->> 'sellable_status',
    p_rule_price_minor,
    p_currency_code,
    v_review_status,
    p_effective_from,
    p_effective_to,
    v_list_price_minor,
    v_floor_price_minor,
    v_price_check_status,
    v_warning_codes,
    nullif(btrim(p_note), ''),
    v_actor_id,
    v_actor_id,
    btrim(p_idempotency_key),
    v_payload_hash
  )
  returning * into v_rule;

  insert into pricing.customer_price_rule_activities (
    tenant_id,
    customer_price_rule_id,
    activity_type,
    new_value,
    created_by
  ) values (
    p_tenant_id,
    v_rule.id,
    'created',
    jsonb_build_object(
      'rule_id', v_rule.id,
      'customer_id', p_customer_id,
      'product_id', p_product_id,
      'product_unit_id', p_product_unit_id,
      'rule_price_minor', p_rule_price_minor,
      'currency_code', p_currency_code,
      'effective_from', p_effective_from,
      'effective_to', p_effective_to,
      'rule_type', 'special_price',
      'source_type', 'manual',
      'status', 'active',
      'review_status', v_review_status,
      'price_check_status', v_price_check_status,
      'warning_codes', v_warning_codes,
      'list_price_snapshot_minor', v_list_price_minor,
      'floor_price_snapshot_minor', v_floor_price_minor,
      'note', nullif(btrim(p_note), ''),
      'version', 1
    ),
    v_actor_id
  );

  return pricing._customer_price_rule_result(
    v_rule.id,
    v_can_override_floor
  );
end;
$$;

revoke all on function pricing.create_customer_price_rule(
  uuid, uuid, uuid, uuid, uuid, bigint, text, date, text, date, text, boolean
) from public, anon;
grant execute on function pricing.create_customer_price_rule(
  uuid, uuid, uuid, uuid, uuid, bigint, text, date, text, date, text, boolean
) to authenticated, service_role;
